const giftArt=g=>`<img class="gift-art" src="${esc(g.image)}" alt="" width="96" height="96" loading="lazy" decoding="async">`;
const giftButton=(t,cls='small-button gift-entry')=>me?.id===t.user_id?'':`<button class="${cls}" data-gift="${esc(t.id)}" aria-label="${esc(t.title)} 선물하기">${icon('gift')}<span>선물</span></button>`;
function giftCards(gifts,selected=null,selectable=false){return `<div class="gift-catalog">${gifts.map(g=>`<${selectable?'button type="button"':'article'} class="gift-choice ${selected===g.id?'selected':''}" ${selectable?`data-gift-type="${g.id}" aria-pressed="${selected===g.id}"`:''}>${giftArt(g)}<strong>${esc(g.name)}</strong><span>${number(g.gold)} G</span></${selectable?'button':'article'}>`).join('')}</div>`;}
function freeRewardsHTML(s,compact=false){const labels={checkin:'오늘 출석',cover:'커버곡 공개',listen:'노래 5곡 감상',comment1:'첫 번째 댓글',comment2:'두 번째 댓글',comment3:'세 번째 댓글'};return `<section class="free-rewards"><div class="free-rewards-title">${giftArt(AifectGifts.FREE_GIFT)}<div><strong>매일 모으는 작은 응원</strong><p>보유 응원별 <b>★ ${number(s?.balance)}</b> · 하루 최대 ★ 10</p></div><span class="free-gift-badge">무료</span></div>${compact?'<details class="gift-reward-details"><summary>오늘의 보상 받기 · 최대 ★ 10</summary>':''}<div class="daily-gift-actions">${s?s.rewards.map(r=>`<div class="daily-gift-task"><span>${labels[r.kind]}<small>${r.kind==='listen'?'곡마다 60% 이상 · '+r.progress+'/5곡':r.kind==='cover'?'하루 1회':r.kind.startsWith('comment')?'3자 이상 · 하루 총 3회':'하루 1회'}</small></span><button type="button" class="small-button" data-claim-gift="${r.kind}" ${r.claimed||!r.eligible?'disabled':''}>${r.claimed?'✓ 받음':r.eligible?'★ '+r.amount+' 받기':'★ '+r.amount+' · '+r.progress+'/'+r.target}</button>${!r.claimed&&!r.eligible?`<a class="text-link" href="${r.kind==='cover'?'#karaoke':'#home'}">${r.kind==='cover'?'커버 공개하기':r.kind==='listen'?'음악 듣기':'곡에서 댓글 남기기'}</a>`:''}</div>`).join(''):'<a class="small-button" href="#account" data-close-dialog>로그인하고 받기</a>'}</div><p class="gift-fineprint">매일 0시(한국 시간) 보상 갱신 · 받은 별은 누적돼요.<br>★ 1 = 1 G = 응원 순위 1점 · 별은 현금 가치·골드 전환·수익 정산이 없어요.</p>${compact?'</details>':''}</section>`;}
function giftShopHTML(d=null){return heading('선물함','좋은 음악에, 마음이 보이는 응원을.')+`<div class="gift-shop-intro"><div><span class="eyebrow">A LITTLE GIFT, A BIG ENCORE</span><h2>오늘의 마음을<br>선물해요.</h2><p>가볍게 건네는 응원별부터 특별한 무대를 위한 왕관까지.<br>음악을 듣다가 재생바의 선물 버튼을 눌러보세요.</p><a href="#community/covers" class="primary-button">선물할 커버곡 찾아보기 ${icon('arrow')}</a></div><div class="gift-shop-art" aria-hidden="true">${giftArt(AifectGifts.giftById('heart'))}${giftArt(AifectGifts.giftById('crown'))}</div></div><div class="gift-shop-actions"><a class="primary-button" href="#rewards">오늘의 응원별 보상 받기</a></div>${section('마음을 전하는 골드 선물')}<p class="gift-catalog-note">골드는 선물 수량이에요. 충전 가격과 창작자 정산액은 각각 별도로 안내해요.</p>${giftCards(d?.gifts||AifectGifts.GIFT_CATALOG)}<div class="gift-shop-actions"><a class="primary-button" href="#gold">골드 충전 · 단건결제</a></div><p class="gift-fineprint">무료 응원별은 지금 모아서 보낼 수 있어요. 별은 수익 정산 대상이 아니에요.</p>${d?`<a href="#gold" class="text-link">보유 골드 ${number(d.balance)} G · 보낸 선물 보기 →</a>`:''}`;}
let giftDialogSerial=0;
async function giftDialog(tid,initial='star'){
 $('#dialog').classList.add('gift-sheet');
 const serial=++giftDialogSerial;dialog('<section class="gift-dialog"><h2>선물하기</h2><p role="status">선물함을 불러오고 있어요…</p></section>');
 try{await accountReady;const [wallet,track]=await Promise.all([me?api('/api/gold'):Promise.resolve(null),api('/api/tracks/'+encodeURIComponent(tid))]);
 if(serial!==giftDialogSerial||!$('#dialog').open)return;const t=track.track;remember([t]);
 if(me?.id===t.user_id){dialog('<h2>내 음악이에요</h2><p>다른 창작자의 음악에 응원을 보내주세요.</p><a class="primary-button" href="#community" data-close-dialog>커뮤니티 둘러보기</a>');return;}
 let chosen=initial==='star'||AifectGifts.giftById(initial)?initial:'star',requestId=crypto.randomUUID();const gifts=wallet?.gifts||AifectGifts.GIFT_CATALOG;
 dialog(`<section class="gift-dialog"><header><span class="eyebrow">SEND YOUR ENCORE</span><h2>음악에 마음을 담아</h2><p><strong>${esc(t.producer)}</strong>에게 · ${esc(t.title)}</p></header><div class="gift-wallet-line"><span>보유 골드 <b>${number(wallet?.balance)} G</b></span><a href="#gold" data-close-dialog>골드 보기 ${icon('chevron')}</a></div><a class="gift-rewards-link" href="#rewards" data-close-dialog>오늘의 응원별 보상 받기</a><form id="gift-form"><div class="gift-options"><button type="button" class="gift-free-choice selected" data-gift-type="star" aria-pressed="true">${giftArt(AifectGifts.FREE_GIFT)}<span><strong>응원별</strong><small>돈 대신 마음으로 · 무료 선물</small></span><b>${number(wallet?.free?.balance )} ★ 보유</b></button><div class="gift-catalog-heading"><h3>골드 선물</h3><a href="#gold" data-close-dialog>골드 충전 →</a></div>${giftCards(gifts,null,true)}</div><div class="gift-send-summary" id="gift-send-summary" aria-live="polite"></div><button type="submit" class="primary-button gift-send-button" id="gift-send"></button><p class="form-error" role="alert"></p></form><p class="gift-fineprint">유료 선물은 골드가 차감돼요. 보낸 선물은 직접 취소할 수 없어요.</p></section>`);
 const form=$('#gift-form');
 const update=()=>{const free=chosen==='star',g=free?AifectGifts.FREE_GIFT:gifts.find(g=>g.id===chosen),balance=free?(wallet?.free?.balance||0):(wallet?.balance||0),cost=free?1:g.gold,enough=balance>=cost;
 form.querySelectorAll('[data-gift-type]').forEach(b=>{b.classList.toggle('selected',b.dataset.giftType===chosen);b.setAttribute('aria-pressed',String(b.dataset.giftType===chosen));});
 $('#gift-send-summary').innerHTML=me?`<span>${esc(g.name)} ${free?'★ 1':number(cost)+' G'}<small>${free?'무료 · 수익에 반영되지 않아요':'충전한 골드에서 차감'}</small></span><strong>${enough?`보낸 뒤 ${number(balance-cost)}${free?' ★':' G'}`:free?'오늘의 보상을 받아주세요':'골드가 부족해요'}</strong>`:'로그인하면 무료 응원별부터 보낼 수 있어요.';
 $('#gift-send').disabled=!!me&&!enough;$('#gift-send').textContent=!me?'로그인하고 선물하기':enough?`${g.name} ${free?'★ 1':number(cost)+' G'} 선물하기`:free?'응원별 받기 후 보낼 수 있어요':wallet.checkout_available?'골드 충전이 필요해요':'골드 충전 준비 중';
 };update();
 form.querySelectorAll('[data-gift-type]').forEach(b=>b.onclick=()=>{if(form._busy)return;chosen=b.dataset.giftType;requestId=crypto.randomUUID();formError(form).textContent='';update();});
 bindGiftClaims($('#gift-rewards'),s=>{wallet.free=s;form.querySelector('.gift-free-choice>b').textContent=number(s.balance)+' ★ 보유';update();});
 form.onsubmit=busyForm(form,async()=>{if(!me){$('#dialog').close();return askLogin();}const type=chosen,g=type==='star'?AifectGifts.FREE_GIFT:gifts.find(g=>g.id===type);$('#gift-send').textContent='보내는 중…';const r=await api(`/api/tracks/${tid}/gifts`,'POST',{gift_type:type,request_id:requestId});
 if(serial!==giftDialogSerial||!form.isConnected)return;
 dialog(`<section class="gift-success"><div class="gift-celebration">${giftArt(g)}</div><span class="eyebrow">THANK YOU FOR YOUR ENCORE</span><h2>${esc(g.name)} 선물을 보냈어요</h2><p>${esc(t.producer)}님의 「${esc(t.title)}」에<br>응원이 전해졌어요.</p><p>${r.gift.free?`남은 응원별 ${number(r.free_balance)} ★ · 수익 정산 없음`:`남은 골드 ${number(r.balance)} G`}</p><button class="primary-button" data-close-dialog>계속 음악 듣기</button></section>`);await render();});
 }catch(e){if(serial===giftDialogSerial&&$('#dialog').open)dialog(`<h2>선물함을 열지 못했어요</h2><p role="alert">${esc(e.message)}</p><button class="primary-button" data-gift="${esc(tid)}">다시 시도</button>`);}
}
function bindGiftClaims(root,onChange=()=>{}){if(!root)return;root.onclick=async e=>{const b=e.target.closest('[data-claim-gift]');if(!b||b.disabled||root._busy||$('#gift-form')?._busy)return;root._busy=true;b.disabled=true;b.textContent='받는 중…';try{const s=await api('/api/gifts/free/claim','POST',{kind:b.dataset.claimGift});if(!root.isConnected)return;root.innerHTML=freeRewardsHTML(s,root.id==='gift-rewards');onChange(s);toast('응원별을 받았어요. 좋아하는 음악에 보내보세요.');}catch(err){toast(err.message);b.disabled=false;b.textContent='다시 받기';}finally{root._busy=false;}};}
async function profileGiftDialog(pid){const d=await api('/api/producers/'+encodeURIComponent(pid)),tracks=[...d.covers,...d.tracks].filter(t=>t.user_id!==me?.id);remember(tracks);dialog(`<h2>${esc(d.profile.name)}님 응원하기</h2><p class="field-help">선물을 보낼 음악을 골라주세요. 선물은 선택한 곡에 기록되어 그 음악의 창작자에게 전달돼요.</p><div class="gift-target-list">${tracks.length?tracks.map(t=>`<button class="gift-target" data-gift="${esc(t.id)}">${cover(t,'mini-cover')}<span><strong>${esc(t.title)}</strong><small>${t.kind==='cover'?'커버곡':'제작곡'}</small></span>${icon('gift')}</button>`).join(''):'<p>선물할 수 있는 공개 곡이 아직 없어요.</p>'}</div>`);}


$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('gift-sheet'));
